Arg::Arg() : buf_(), len_(0) {
  buf_[0] = '\0';
}

void Arg::clear() {
  len_ = 0;
  buf_[0] = '\0';
}

bool Arg::push(char c) {
  if (len_ >= kMaxArgLen) {
    return false;
  }
  buf_[len_] = c;
  len_ = static_cast<uint8_t>(len_ + 1U);
  buf_[len_] = '\0';
  return true;
}

bool Arg::set(const char* s, size_t n) {
  clear();
  if (s == nullptr) {
    return true;
  }
  for (size_t i = 0; i < n; ++i) {
    if (!push(s[i])) {
      return false;
    }
  }
  return true;
}

bool Arg::set(const char* s) {
  clear();
  if (s == nullptr) {
    return true;
  }
  for (size_t i = 0; s[i] != '\0'; ++i) {
    if (!push(s[i])) {
      return false;
    }
  }
  return true;
}

void Arg::setU32(uint32_t v) {
  // Ten digits is the widest uint32_t, so this always fits in kMaxArgLen.
  char digits[10];
  size_t n = 0;
  do {
    digits[n] = static_cast<char>('0' + static_cast<int>(v % 10U));
    ++n;
    v /= 10U;
  } while (v != 0U && n < sizeof(digits));

  clear();
  while (n > 0) {
    --n;
    static_cast<void>(push(digits[n]));
  }
}

bool Arg::equals(const char* s) const {
  return s != nullptr && sameText(buf_, s);
}

