namespace {

const char* const kEmpty = "";

uint16_t clampSeconds(uint32_t seconds, uint16_t lowest, uint16_t highest) {
  if (seconds < lowest) {
    return lowest;
  }
  if (seconds > highest) {
    return highest;
  }
  return static_cast<uint16_t>(seconds);
}

/// A court number as the glass can show it. Negative is not a court number and
/// four digits is all the cell has.
uint32_t clampCourtNumber(int16_t number) {
  if (number <= 0) {
    return 0U;
  }
  return number > 9999 ? 9999U : static_cast<uint32_t>(number);
}

} // namespace

Frame::Frame() : verb_(Verb::Unknown), argc_(0), args_() {
}

Frame Frame::ofVerb(Verb v) {
  Frame f;
  f.verb_ = v;
  return f;
}

bool Frame::pushArg(const char* s) {
  if (argc_ >= kMaxArgs) {
    return false;
  }
  const bool fitted = args_[argc_].set(s);
  argc_ = static_cast<uint8_t>(argc_ + 1U);
  return fitted;
}

bool Frame::pushArgChar(char c) {
  if (argc_ >= kMaxArgs) {
    return false;
  }
  args_[argc_].clear();
  const bool fitted = args_[argc_].push(c);
  argc_ = static_cast<uint8_t>(argc_ + 1U);
  return fitted;
}

bool Frame::pushArgU32(uint32_t v) {
  if (argc_ >= kMaxArgs) {
    return false;
  }
  args_[argc_].setU32(v);
  argc_ = static_cast<uint8_t>(argc_ + 1U);
  return true;
}

bool Frame::pushArgHex(uint32_t v, uint8_t digits) {
  if (argc_ >= kMaxArgs) {
    return false;
  }
  args_[argc_].clear();
  for (uint8_t i = digits; i > 0U; --i) {
    const uint8_t nibble = static_cast<uint8_t>((v >> (4U * (i - 1U))) & 0x0FU);
    static_cast<void>(args_[argc_].push(nibble < 10U ? static_cast<char>('0' + nibble)
                                                     : static_cast<char>('A' + (nibble - 10U))));
  }
  argc_ = static_cast<uint8_t>(argc_ + 1U);
  return true;
}

bool Frame::pushArgOpinion(int32_t v, uint32_t lowest, uint32_t highest) {
  if (v < 0) {
    return pushArg("-");
  }
  uint32_t u = static_cast<uint32_t>(v);
  u = u < lowest ? lowest : (u > highest ? highest : u);
  return pushArgU32(u);
}

Frame Frame::fromValidated(const VerbSpec& spec, const Arg* args, uint8_t argc) {
  Frame f = ofVerb(spec.verb);
  for (uint8_t i = 0; i < argc && i < kMaxArgs; ++i) {
    static_cast<void>(f.pushArg(args[i].c_str()));
  }
  return f;
}

