Frame Frame::lcd(const char* line1, const char* line2) {
  // Truncation is deliberate here and only here: the panel is driven as 16
  // columns, so text past kMaxArgLen was never going to be read by anybody.
  Frame f = ofVerb(Verb::Lcd);
  static_cast<void>(f.pushArg(line1));
  static_cast<void>(f.pushArg(line2));
  return f;
}

Frame Frame::row(uint8_t row, const char* text) {
  if (row >= kMaxRows) {
    return Frame();
  }
  Frame f = ofVerb(Verb::Row);
  static_cast<void>(f.pushArgU32(row));
  // Truncation, as lcd()'s: a row wider than the panel was never going to be
  // read. The ROW INDEX is what is refused, because that is the one that names
  // somewhere the text would silently land instead.
  static_cast<void>(f.pushArg(text));
  return f;
}

