Frame Frame::scan(const char* code) {
  // A truncated scanner code is a DIFFERENT member, so this refuses rather than
  // shortening. The caller gets an empty Frame, which encodes to nothing.
  Frame f = ofVerb(Verb::Scan);
  if (!f.pushArg(code)) {
    return Frame();
  }
  return f;
}

