  static_cast<void>(f.pushArgU32(relayLevel > 1U ? 1U : relayLevel));
  static_cast<void>(f.pushArgU32(baudCode > 5U ? 5U : baudCode));
  static_cast<void>(f.pushArgU32(lineEnd > 1U ? 1U : lineEnd));
  static_cast<void>(f.pushArgHex(keys, 2U));
