const char* Frame::arg(uint8_t i) const {
  return i < argc_ ? args_[i].c_str() : kEmpty;
}

bool Frame::operator==(const Frame& other) const {
  if (verb_ != other.verb_ || argc_ != other.argc_) {
    return false;
  }
  for (uint8_t i = 0; i < argc_; ++i) {
    if (!args_[i].equals(other.args_[i].c_str())) {
      return false;
    }
  }
  return true;
}

